private boolean isValidKeyword(String value)
{
    // Check for valid CSS font-size keywords
    return value.equals("smaller") || value.equals("larger") || value.equals("inherit") || isFontSizeKeyword(value);
}

private boolean isFontSizeKeyword(String value)
{
    // You should expand this based on all acceptable CSS font-size keywords
    return value.equals("medium") || value.equals("xx-small") || value.equals("x-small") || value.equals("small") || 
           value.equals("large") || value.equals("x-large") || value.equals("xx-large");
}

private boolean isUsageMessageKeyword(String value)
{
    // Adjust this logic if more keywords should trigger a usage message
    return value.equals("smaller") || value.equals("larger");
}
